<?php
require __DIR__.'/app/bootstrap.php';require_login();require __DIR__.'/app/layout.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;
$st=$pdo->prepare('SELECT a.*,r.registration_date,r.office_name,r.notes registration_notes FROM applicants a LEFT JOIN registrations r ON r.applicant_id=a.id WHERE a.id=?');$st->execute([$id]);$a=$st->fetch();if(!$a){flash('error','Applicant not found.');redirect('applicants.php');}
$c=$pdo->prepare('SELECT * FROM id_cards WHERE applicant_id=? ORDER BY created_at DESC');$c->execute([$id]);$cards=$c->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(($_POST['action']??'')==='delete'){if(($_POST['confirm']??'')!=='DELETE') {flash('error','Type DELETE in the confirmation field to remove this applicant.');redirect('applicant_view.php?id='.$id);}try{$pdo->beginTransaction();$pdo->prepare('DELETE FROM id_cards WHERE applicant_id=?')->execute([$id]);$pdo->prepare('DELETE FROM registrations WHERE applicant_id=?')->execute([$id]);$pdo->prepare('DELETE FROM applicants WHERE id=?')->execute([$id]);$pdo->commit();log_activity($pdo,'DELETE_APPLICANT',null,'Deleted applicant record ID '.$id);flash('success','Applicant and related records deleted.');redirect('applicants.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log($e->getMessage());flash('error','Unable to delete this record.');redirect('applicant_view.php?id='.$id);}}
}
page_header('Applicant details'); ?>
<div class="detail-toolbar"><div><span class="muted">Applicant number</span><h2><?=e($a['applicant_no'])?></h2></div><div class="toolbar-actions"><a class="btn secondary" href="applicants.php">← Back</a><a class="btn secondary" href="applicant_form.php?id=<?=$id?>">Edit record</a><a class="btn primary" href="card_form.php?applicant_id=<?=$id?>">＋ Record ID card</a></div></div>
<div class="detail-grid"><section class="panel"><div class="panel-heading"><h2>Personal information</h2><span class="pill"><?=e($a['status'])?></span></div><dl class="details"><?php foreach(['Full name'=>$a['first_name'].' '.$a['last_name'],'Date of birth'=>$a['date_of_birth'],'Sex'=>$a['sex'],'Phone'=>$a['phone']?:'—','Email'=>$a['email']?:'—','Nationality'=>$a['nationality'],'District'=>$a['district']?:'—','Address'=>$a['address']?:'—','Registration date'=>$a['registration_date']?:'—','Registration office'=>$a['office_name']?:'—'] as $k=>$v): ?><div><dt><?=e($k)?></dt><dd><?=e($v)?></dd></div><?php endforeach; ?></dl></section><section class="panel"><div class="panel-heading"><h2>ID card records</h2></div><?php if(!$cards): ?><p class="empty">No ID card issuance records yet.</p><?php else: foreach($cards as $card): ?><div class="card-record"><strong><?=e($card['card_number'])?></strong><span class="pill"><?=e($card['status'])?></span><p class="muted">Issued: <?=e($card['issue_date']?:'Not issued')?> · Expires: <?=e($card['expiry_date']?:'—')?></p><a href="card_form.php?id=<?=(int)$card['id']?>">Manage card →</a></div><?php endforeach; endif; ?></section></div>
<section class="panel danger-zone"><h2>Danger zone</h2><p class="muted">Deletion permanently removes this applicant and their registration/card records.</p><form method="post" class="delete-form" onsubmit="return confirm('Permanently delete this fictional applicant and related records?');"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><label>Type DELETE to confirm<input name="confirm" required pattern="DELETE" autocomplete="off"></label><button class="btn danger" type="submit">Delete applicant</button></form></section>
<?php page_footer(); ?>
